<template><span class="user-avatar" :style="{'--avatar-size':`${size}px`}" aria-hidden="true"><img v-if="src" :src="src" alt="" draggable="false"/><span v-else class="avatar-fallback">{{ letter }}</span></span></template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';import {createUserAvatarBlobUrl,directAvatarUrl} from '@/api/profile'
const props=withDefaults(defineProps<{userId:number;avatar?:string|null;name?:string|null;size?:number}>(),{avatar:null,name:'旅',size:40});const src=ref('');let objectUrl='';let version=0;const letter=computed(()=>((props.name||'旅').trim().slice(0,1).toUpperCase()));function release(){if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}src.value=''}async function load(){const current=++version;release();const direct=directAvatarUrl(props.avatar);if(direct){src.value=direct;return}if(!props.avatar||!props.userId)return;try{const url=await createUserAvatarBlobUrl(props.userId);if(current!==version){if(url)URL.revokeObjectURL(url);return}objectUrl=url;src.value=url}catch(e){console.debug('头像读取失败：',e)}}watch([()=>props.userId,()=>props.avatar],()=>void load(),{immediate:true});onBeforeUnmount(()=>{++version;release()})
</script>
<style scoped>.user-avatar{width:var(--avatar-size);height:var(--avatar-size);flex:0 0 var(--avatar-size);display:inline-grid;place-items:center;overflow:hidden;border:2px solid rgba(255,255,255,.86);border-radius:50%;color:#914f72;font-weight:900;background:linear-gradient(145deg,#ffd5e6,#fff0c3);box-shadow:0 8px 22px rgba(208,112,153,.18)}.user-avatar img{width:100%;height:100%;display:block;object-fit:cover}.avatar-fallback{line-height:1}</style>
